cd /testbed && patch -p1 <<'PATCH'
--- /dev/null
+++ b/tests/unit/cluster/cluster-shards.tcl
@@ -0,0 +1,96 @@
+proc get_shard_by_node_id {reference node_id} {
+    foreach shard [R $reference CLUSTER SHARDS] {
+        foreach node [dict get $shard nodes] {
+            if {[dict get $node id] eq $node_id} {
+                return $shard
+            }
+        }
+    }
+    fail "Node $node_id not found in CLUSTER SHARDS on node $reference"
+}
+
+start_cluster 3 3 {tags {external:skip cluster} overrides {cluster-replica-no-failover yes}} {
+    set primary_id [R 0 CLUSTER MYID]
+    set replica_id [R 3 CLUSTER MYID]
+    set slot_ranges {{0 5461} {5462 10922} {10923 16383}}
+
+    test "CLUSTER SHARDS reports slot ranges on primaries and replicas" {
+        for {set reference 0} {$reference < 6} {incr reference} {
+            assert_equal 3 [llength [R $reference CLUSTER SHARDS]]
+            for {set node 0} {$node < 6} {incr node} {
+                set shard [get_shard_by_node_id $reference [R $node CLUSTER MYID]]
+                assert_equal [lindex $slot_ranges [expr {$node % 3}]] [dict get $shard slots]
+                assert_equal 2 [llength [dict get $shard nodes]]
+            }
+        }
+    }
+
+    test "CLUSTER SHARDS reports discontinuous and empty slot ranges" {
+        R 0 CLUSTER DELSLOTS 10 12
+        assert_equal {0 9 11 11 13 5461} [dict get [get_shard_by_node_id 0 $primary_id] slots]
+        R 0 CLUSTER ADDSLOTS 10 12
+
+        set empty_id [R 2 CLUSTER MYID]
+        R 2 CLUSTER DELSLOTSRANGE 10923 16383
+        assert_equal {} [dict get [get_shard_by_node_id 2 $empty_id] slots]
+        R 2 CLUSTER ADDSLOTSRANGE 10923 16383
+    }
+
+    set paused_pid [srv 0 pid]
+    test "CLUSTER SHARDS preserves slot ranges while the primary is failed" {
+        pause_process $paused_pid
+        for {set reference 1} {$reference < 6} {incr reference} {
+            wait_for_condition 1000 50 {
+                [cluster_has_flag [cluster_get_node_by_id $reference $primary_id] fail]
+            } else {
+                fail "Node $reference did not detect the failed primary"
+            }
+            assert_equal {0 5461} [dict get [get_shard_by_node_id $reference $primary_id] slots]
+        }
+    }
+
+    test "CLUSTER SHARDS preserves slot ranges after failover with two primaries" {
+        R 3 CLUSTER FAILOVER TAKEOVER
+        for {set reference 1} {$reference < 6} {incr reference} {
+            wait_for_condition 1000 50 {
+                [dict get [cluster_get_node_by_id $reference $replica_id] slots] eq {0-5461}
+            } else {
+                fail "Node $reference did not learn the promoted primary's slots"
+            }
+            assert {[cluster_has_flag [cluster_get_node_by_id $reference $primary_id] master]}
+            assert {[cluster_has_flag [cluster_get_node_by_id $reference $primary_id] fail]}
+            for {set attempt 0} {$attempt < 2} {incr attempt} {
+                set shard [get_shard_by_node_id $reference $primary_id]
+                assert_equal {0 5461} [dict get $shard slots]
+                assert_equal 2 [llength [dict get $shard nodes]]
+                foreach node [dict get $shard nodes] {
+                    assert_equal master [dict get $node role]
+                    if {[dict get $node id] eq $primary_id} {
+                        assert_equal fail [dict get $node health]
+                    } else {
+                        assert_equal $replica_id [dict get $node id]
+                        assert_equal online [dict get $node health]
+                    }
+                }
+            }
+        }
+    }
+
+    resume_process $paused_pid
+    test "CLUSTER SHARDS preserves slot ranges after the former primary rejoins" {
+        wait_for_condition 1000 50 {
+            [s 0 role] eq {slave}
+        } else {
+            fail "The former primary did not become a replica"
+        }
+        wait_for_cluster_propagation
+        for {set reference 0} {$reference < 6} {incr reference} {
+            assert_equal {0 5461} [dict get [get_shard_by_node_id $reference $primary_id] slots]
+        }
+    }
+}
PATCH
